// smart-textiles-study-data.js — the content of /smart-textiles-study.html: the mnemonic cards, the
// quiz, the metal cards, the two scenario games and the stack-ups. Pure data; no DOM.
//
// Numbers are room-temperature handbook values, rounded. Where a value depends on the product (a
// yarn's ohms per metre, a polymer's conductivity) the copy says "typical" and gives an order of
// magnitude rather than a spec. Chapters: flow, resist, metals, sense, stack.

export const CHAPTERS = [
  { id: 'flow', n: '01', name: 'Electrons and the Push', anchor: '#flow' },
  { id: 'resist', n: '02', name: 'Why a Yarn Resists', anchor: '#resist' },
  { id: 'metals', n: '03', name: 'Choosing the Metal', anchor: '#metals' },
  { id: 'sense', n: '04', name: 'Resistive vs Capacitive', anchor: '#sense' },
  { id: 'stack', n: '05', name: 'Stack-Ups', anchor: '#stack' },
  { id: 'stretch', n: '06', name: 'Stretch and Stiffness', anchor: '#stretch' },
];

// ---------------------------------------------------------------------------------------------
// THE CONTACT LINE. What a touching point between yarns does to resistance. Three candidates; the
// pick is CONTACT_PICK and nothing else, so swapping the line is one number. The card, its "Type the
// line" blanks, the chapter 02 figure's caption and drawing, and the knit question's explanation all
// read CONTACT. Each candidate predicts the right direction for both cases the page teaches: press a
// resistive pad (more touch, R falls) and stretch the knit (loops part, less touch, R rises). The
// toll-booth image it replaces is kept as an alternate, scoped to joints in series, where it's right.
// ---------------------------------------------------------------------------------------------
export const CONTACT_LINES = [
  { hook: 'Touch more, resist less.', cloze: ['Touch', 'less'], short: 'touch more, resist less' },
  { hook: 'Contacts are bridges: lose a bridge, add a jam.', cloze: ['bridges', 'jam'], short: 'contacts are bridges' },
  { hook: 'Fewer touches, fewer roads.', cloze: ['touches', 'roads'], short: 'fewer touches, fewer roads' },
];
export const CONTACT_PICK = 0;
export const CONTACT = CONTACT_LINES[CONTACT_PICK];

// ---------------------------------------------------------------------------------------------
// MNEMONIC CARDS. front = the question, hook = the line to remember, back = why it is true.
// ---------------------------------------------------------------------------------------------
export const CARDS = [
  // 01 flow
  { id: 'ohm', ch: 'flow', front: 'Ohm’s law, in plain words', hook: 'Push = Flow × Fight', back: 'V = I · R. Voltage is the push, current is how much charge gets through per second, resistance is how hard the path fights it. Hold any two and the third is fixed.' },
  { id: 'arrow', ch: 'flow', front: 'Which way does current flow?', hook: 'Electrons leave the minus; the arrow leaves the plus.', back: 'Franklin picked the sign in the 1740s, a century and a half before anyone found the electron. Diagrams kept his arrow (+ to −). The electrons actually run the other way. Both describe the same circuit.' },
  { id: 'marbles', ch: 'flow', front: 'If electrons crawl, why does the LED light instantly?', hook: 'A tube full of marbles: each barely moves, the push arrives at once.', back: 'In copper at 1 A per mm² an electron drifts about 0.07 mm a second. The wire is already full of them, so pushing at one end moves every electron along the path at nearly the same moment.' },
  { id: 'loop', ch: 'flow', front: 'Why does a single thread from + to an LED do nothing?', hook: 'No loop, no flow.', back: 'Charge has to come back to the source. Every circuit is a closed loop: out of one terminal, through the load, back into the other.' },
  { id: 'sweatroad', ch: 'flow', front: 'What does a sweat droplet between two traces do?', hook: 'Current takes the easy road — and sweat builds roads.', back: 'Salty water conducts. A bridge between two traces is a second path in parallel with your sensor, so part of the current skips it and the reading lies. That’s why traces get encapsulated.' },
  // 02 resist
  { id: 'longthin', ch: 'resist', front: 'R = ρL/A, as a rhyme', hook: 'Long and thin, resistance wins.', back: 'Resistance grows with length and shrinks with cross-section. Double the length, double the R. Double the cross-section, half the R. ρ is the material’s own share.' },
  { id: 'tex', ch: 'resist', front: 'ρ (Ω·m) vs Ω/m on a yarn datasheet', hook: 'Ω/m is the tex of conductivity.', back: 'Resistivity ρ is a material property, like fibre density in g/cm³. A yarn’s Ω/m bakes in how much conductor is in the cross-section, the way tex bakes in how much fibre is in a kilometre. Compare yarns by Ω/m; compare materials by ρ.' },
  { id: 'lanes', ch: 'resist', front: 'Ply two identical conductive yarns together. What happens to R?', hook: 'More lanes, less jam.', back: 'Side-by-side paths are in parallel: n equal paths give R ÷ n. Paths end to end are in series and add. A multifilament yarn is many lanes, which is also why a few broken filaments only nudge R up.' },
  { id: 'toll', ch: 'resist', front: 'Why does a conductive knit change resistance when you stretch it?', hook: CONTACT.hook, back: 'Current hops loop to loop wherever yarns touch, and every touching point is a path. More points touching, and pressing harder, means more paths side by side and a lower R. Stretch pulls this knit’s loops apart, so fewer touch and R rises; some knits press tighter at first and R falls. Joints in series (a snap, then a crimp) are the other case: each one adds its own resistance.' },
  { id: 'square', ch: 'resist', front: 'Double the current through a heater yarn. How much more heat?', hook: 'Heat goes with the square.', back: 'P = I²R. Twice the current, four times the heat. A thin or damaged spot in a series line carries the same current at higher R, so it runs hottest.' },
  { id: 'colder', ch: 'resist', front: 'Fixed 5 V battery. Make the heater line twice as long?', hook: 'At fixed voltage, longer is colder.', back: 'P = V²/R. A longer line has more R, so it draws less current and makes less heat in total. To cover a big panel at low voltage, run several shorter lines in parallel.' },
  // 03 metals
  { id: 'cats', ch: 'metals', front: 'The four best metallic conductors, in order', hook: 'Some Cats Get Angry — Ag, Cu, Au, Al.', back: 'Silver 1.59, copper 1.68, gold 2.44, aluminium 2.65 (×10⁻⁸ Ω·m). Silver and copper are within 6% of each other. Stainless steel is about 43× worse than copper.' },
  { id: 'silver', ch: 'metals', front: 'Silver: what it’s good for and how it fails', hook: 'Best conductor, kills microbes — turns black and walks in the wet.', back: 'Silver tarnishes to silver sulfide, which raises contact resistance. Under DC bias with moisture, silver ions migrate and grow dendrites that can short close traces. It’s still the default for skin electrodes and plated yarns.' },
  { id: 'copper', ch: 'metals', front: 'Why is textile copper never bare?', hook: 'Copper is always dressed — enamel, plating or alloy.', back: 'Nearly silver’s conductivity at a fraction of the price, but it oxidises, corrodes green in sweat, can stain skin and work-hardens until it snaps under flexing. Enamel insulates it; alloying with silver toughens it.' },
  { id: 'gold', ch: 'metals', front: 'Where does gold go?', hook: 'Gold goes where things touch.', back: 'Gold doesn’t tarnish, so a gold contact face keeps a stable, low contact resistance through thousands of connections. It’s too expensive for bulk, so it’s a thin plate, usually over a nickel barrier.' },
  { id: 'stainless', ch: 'metals', front: 'Stainless steel fibre: the trade', hook: 'The workhorse: washes forever, conducts like a tax.', back: 'A chromium-oxide skin heals itself, so it survives sweat and laundry. The price is about 43× copper’s resistivity, and it’s hard to solder. Good for durable traces, electrodes and heaters.' },
  { id: 'nickel', ch: 'metals', front: 'The rule for nickel', hook: 'Nickel near skin = itch.', back: 'Nickel is the most common contact allergen. It shows up as plating on snaps and as an underlayer beneath gold. Keep exposed nickel off skin.' },
  { id: 'galvanic', ch: 'metals', front: 'Two different metals touching in sweat', hook: 'Two metals + sweat = a battery; the less noble one pays.', back: 'Sweat is an electrolyte. The more active metal (copper next to silver, for example) gives up electrons and dissolves, so the joint corrodes from that side.' },
  { id: 'tcr', ch: 'metals', front: 'Heater wire vs thermometer wire', hook: 'Heaters want steady; thermometers want swingy.', back: 'Nichrome barely changes resistance as it heats, so its power stays predictable. Platinum (+0.385% per °C), copper (+0.39%) and nickel (+0.6%) change a lot and predictably, which is what a sensor wants. Constantan barely changes at all, which is why strain gauges use it.' },
  { id: 'carbon', ch: 'metals', front: 'Carbon in a smart textile', hook: 'Carbon senses, metals carry.', back: 'Carbon fibre conducts about a thousand times worse than copper, and carbon-filled polymers millions of times worse, and its resistance moves when it’s squeezed or stretched. That makes it a sensor or heater material, not wiring.' },
  { id: 'pedot', ch: 'metals', front: 'PEDOT:PSS', hook: 'Paint that conducts — and water is its enemy.', back: 'A conductive polymer you can coat, print or dye onto fibres. It’s soft and nearly invisible, but the PSS half drinks water, so humidity and washing degrade it.' },
  { id: 'enamel', ch: 'metals', front: 'Why enamel on a silver–copper alloy filament?', hook: 'Enamel lets lines cross; heat opens the door.', back: 'The thin polyurethane coat insulates, so two lines can cross without shorting and the wire can lie against skin. Soldering heat burns the enamel off only where you join it. Where two enamelled wires cross, the enamel is the gap of a tiny capacitor.' },
  // 04 sense
  { id: 'roadcanyon', ch: 'sense', front: 'Resistive vs capacitive, in one line', hook: 'R is a Road, C is a Canyon.', back: 'Resistive: current travels through the sensing material, and pressing adds lanes. Capacitive: an insulator stops the current, charge piles up on both rims, and pressing brings the rims closer so more charge fits.' },
  { id: 'cformula', ch: 'sense', front: 'C = ε₀εᵣA/d — what raises capacitance?', hook: 'Bigger plates, better filling, smaller gap.', back: 'A is the overlap area, d the gap, εᵣ the relative permittivity of what fills the gap (air 1, polyester about 3, water about 80) and ε₀ a constant. Halve the gap, double the C.' },
  { id: 'bucket', ch: 'sense', front: 'How does a chip measure capacitance?', hook: 'C is a bucket: bigger bucket, longer to fill.', back: 'It charges the electrode through a known resistor and times how long the voltage takes to reach a threshold (t ∝ RC), or counts an oscillator’s frequency. More C, more time.' },
  { id: 'divider', ch: 'sense', front: 'How does a chip read a resistive sensor?', hook: 'Two resistors share the push in proportion.', back: 'Put the sensor in series with a fixed resistor across the supply and measure the voltage at the middle. The bigger resistor takes the bigger share, so as the sensor’s R falls its share of the voltage falls.' },
  { id: 'selfmutual', ch: 'sense', front: 'A finger approaches a capacitive electrode', hook: 'Self: you add. Mutual: you steal.', back: 'Self-capacitance: your body is an extra plate to ground, so the measured C goes up. Mutual capacitance: you intercept field lines between a transmit and a receive electrode, so the measured C between them goes down.' },
  { id: 'water', ch: 'sense', front: 'What does water do to each sensor type?', hook: 'Water fools C and shorts R.', back: 'Water’s relative permittivity εᵣ is about 80, so a damp patch looks like a huge touch to a capacitive sensor. To a resistive one, sweat is a conductor that bridges the electrodes.' },
  { id: 'shield', ch: 'sense', front: 'Why do capacitive pads need a ground shield?', hook: 'Your body is a 100 pF giant next to a 1 pF sensor.', back: 'Two 2 cm × 2 cm plates 3 mm apart in air make about 1.2 pF. A body is around 100 pF to ground. Without a grounded layer between them, the sensor responds to your leg instead of the press.' },
  { id: 'remember', ch: 'sense', front: 'The weakness of resistive pressure sensors', hook: 'Polymers remember.', back: 'The carbon-loaded layer creeps under a steady load (drift) and reads differently on the way back down (hysteresis). Capacitive pads with a springy spacer drift far less.' },
  { id: 'switch', ch: 'sense', front: 'Two conductive fabrics with nothing between them', hook: 'No middle layer, no middle values.', back: 'Without the carbon layer, the electrodes either touch or they don’t. That’s a switch. The resistive layer is what turns force into a range of values.' },
  // 05 stack
  { id: 'base', ch: 'stack', front: 'Why print silver ink onto a TPU layer instead of straight onto fabric?', hook: 'Fabric is a sieve; TPU is a floor.', back: 'On bare fabric the ink wicks into the yarn gaps and breaks into islands. A laminated TPU base gives it a continuous surface, and a top TPU layer protects it from abrasion and washing.' },
  { id: 'pressure', ch: 'stack', front: 'What makes a dry EMG electrode quiet?', hook: 'Contact pressure is signal quality.', back: 'The skin under the electrode is part of the circuit. If contact shifts, the electrode-skin impedance changes and that change looks like signal (motion artefact). Compression holds the contact steady.' },
  { id: 'insulated', ch: 'stack', front: 'An EMG trace runs bare against the skin to its snap', hook: 'A bare trace is a second electrode.', back: 'It picks up signal along its whole length. Everything but the electrode window must be insulated.' },
  { id: 'heaterout', ch: 'stack', front: 'Why is there insulation outside a heater?', hook: 'Heat flows both ways.', back: 'Without an insulating layer outward, a large share of the heat goes to the outside air instead of to the body.' },
  // 06 · stretch and stiffness
  { id: 'strain', ch: 'stretch', front: 'What is strain?', hook: 'Strain is stretch per length.', back: 'ε = ΔL / L. Pull a 100 mm strip to 110 mm and the strain is 0.10, or 10%. Because it’s a ratio it has no units, so a thin wire and a whole garment can be compared on the same scale.' },
  { id: 'young', ch: 'stretch', front: 'What is Young’s modulus?', hook: 'Stiffness is stress over strain.', back: 'E = σ / ε: the stress (force per cross-section area) it takes per unit of strain, read off the straight first part of the stress–strain curve. High E: a lot of stress for a little stretch.' },
  { id: 'modscale', ch: 'stretch', front: 'How far apart are the stiffnesses inside one smart garment?', hook: 'Metal is a hundred thousand times stiffer than silicone.', back: 'Carbon fibre about 230 GPa, stainless steel ~190, copper ~120, silver ~80, polyester fibre ~10, nylon ~3, TPU about 0.01–0.05 GPa, silicone about 0.001 GPa (1 MPa; the softest grades used in stretchable electronics, about 0.05 MPa). Every place a stiff part meets a soft one is a place where strain piles up.' },
  { id: 'yield', ch: 'stretch', front: 'Why can’t a straight copper trace survive a fabric that stretches 20%?', hook: 'Metal only springs back a tiny bit.', back: 'Copper is elastic only up to roughly 0.03–0.3% strain: the low end for soft (annealed) copper, the high end for hard-drawn. Past that it yields: it stays longer when you let go, and repeated cycles crack it. Fabric stretches 10–50% in normal wear.' },
  { id: 'poisson', ch: 'stretch', front: 'What is Poisson’s ratio?', hook: 'Pull it long, it goes thin.', back: 'ν = − (sideways strain) / (stretch strain). Stretch a strip 10% and, with ν = 0.3, it narrows about 3%. The minus sign makes ν positive for ordinary materials, which narrow when you pull them.' },
  { id: 'poissonvals', ch: 'stretch', front: 'What are typical values of Poisson’s ratio?', hook: 'Cork zero, metal a third, rubber a half.', back: 'Cork ≈ 0, metals ≈ 0.3, rubber and silicone ≈ 0.5. At 0.5 a stretched material keeps its volume. An isotropic material (the same in every direction) can’t go above 0.5; structures like weaves and knits, which aren’t, can.' },
  { id: 'auxetic', ch: 'stretch', front: 'What does an auxetic structure do when you pull it?', hook: 'Auxetics get fatter when you pull.', back: 'Its Poisson’s ratio is negative. The cells are re-entrant (pointing inward, like a bow tie); pulling straightens them, and that pushes the cells apart sideways too. Used for padding and spacers that wrap round curved body parts.' },
  { id: 'bias', ch: 'stretch', front: 'Why does a woven fabric pulled on the bias narrow so much?', hook: 'On the bias the yarns turn instead of stretching.', back: 'Pulled at 45° the warp and weft crossings act like scissors: the angle between them closes, so the fabric gets long and narrow while hardly any yarn stretches. Its apparent Poisson’s ratio can be 1 or more, which only a structure can do.' },
  { id: 'gaugefactor', ch: 'stretch', front: 'Why does stretching a conductor raise its resistance by more than the stretch?', hook: 'Longer and thinner: hit twice.', back: 'R = ρL/A. Stretch by ε and L grows by ε while A shrinks by about 2νε. Together R rises by about (1 + 2ν) × ε. That ratio, (ΔR/R)/ε, is the gauge factor: about 1.7 for metal from shape alone, 2 for a liquid metal.' },
  { id: 'capstretch', ch: 'stretch', front: 'What happens to a soft capacitor’s capacitance when you stretch it?', hook: 'Stretch a rubber capacitor and C rises in step.', back: 'C = ε₀εᵣA/d. In a rubbery layer (ν = ½) stretched λ times, the length goes ×λ, width ×1/√λ, so area ×√λ; the gap goes ×1/√λ. C goes ×λ: stretch 50%, C up 50%. That straight line is why stretchable capacitive strain sensors read so cleanly.' },
  { id: 'mismatch', ch: 'stretch', front: 'A stiff pod is glued onto a stretchy sleeve. Where does it fail?', hook: 'Stiff on soft breaks at the edge.', back: 'The pod hardly stretches, so the soft material beside it has to take all the stretch, and the strain concentrates at the pod’s edges. That’s where adhesive peels, traces crack and seams tear. Step the stiffness down gradually (a middle-stiff layer, a rounded or tapered edge) to spread it.' },
  { id: 'serpentine', ch: 'stretch', front: 'How do you run a metal trace across fabric that stretches 30%?', hook: 'Serpentines turn stretch into bend.', back: 'Lay it as a wave (serpentine) or a coil. As the fabric stretches the wave straightens, so the metal bends a little instead of stretching. A narrow trace with wide curves can bend far more than it can stretch before it yields.' },
  { id: 'bendcube', ch: 'stretch', front: 'Why does a film twice as thick feel so much more than twice as stiff?', hook: 'Twice as thick, eight times as stiff.', back: 'Bending stiffness goes as E × t³. Double a TPU film’s thickness and it resists bending 8 times as much; halve it and it bends 8 times as easily. Stacked layers stiffen a garment faster than you’d guess.' },
  { id: 'jcurve', ch: 'stretch', front: 'Why does a knit feel soft at first and then suddenly stiff?', hook: 'A knit is soft, then stiff: a J.', back: 'First the loops reshape and slide, which takes little force. Once they’re pulled taut the fibres themselves carry the load and the force rises steeply. No single Young’s modulus describes a knit; read its curve at the stretch you’ll actually use.' },
];

// ---------------------------------------------------------------------------------------------
// QUIZ. a = index of the right option. why = the explanation shown after answering.
// ---------------------------------------------------------------------------------------------
export const QUIZ = [
  // flow
  { id: 'q-drift', ch: 'flow', q: 'You switch on a circuit sewn in conductive thread. How fast does an individual electron in the yarn move along it?', o: ['Close to the speed of light, as the signal does', 'About walking pace, a metre or so a second', 'Fractions of a millimetre a second', 'Not at all: only the push travels'], a: 2, why: 'Drift velocity is tiny (about 0.07 mm/s in copper at 1 A per mm²). What travels at a large fraction of light speed is the electric field along the wire, which sets every electron moving at almost the same moment: marbles in a tube.', no: ['That is the speed of the signal: the electric field runs down the wire almost at once. The electrons themselves only creep along behind it.', 'Walking pace would carry an electron round a garment circuit in a second or two. There are so many free electrons sharing the current that each one drifts thousands of times slower.', null, 'They do move, since a current is moving charge. The steady drift is just very slow and hidden under the much faster random jiggle of heat.'] },
  { id: 'q-arrow', ch: 'flow', q: 'In a circuit diagram, the current arrow points…', o: ['from + to −, opposite to the electrons', 'from − to +, the way the electrons go', 'from + to −, the same way as the electrons', 'whichever way the battery is drawn'], a: 0, why: 'Conventional current is Franklin’s sign convention, kept for 250 years. Electrons leave the minus terminal; the arrow leaves the plus.', no: [null, 'That is the way the electrons move. The arrow was fixed before anyone knew about electrons, and it points the other way.', 'The arrow does run from + to −, but electrons carry negative charge, so they travel toward + instead.', 'The convention doesn’t depend on how a diagram is laid out: it always runs from the + terminal round to the −.'] },
  { id: 'q-doubleV', ch: 'flow', q: 'Double the voltage across the same yarn. The current…', o: ['halves', 'stays the same', 'doubles', 'quadruples'], a: 2, why: 'I = V / R. Same fight, twice the push, twice the flow.', no: ['Halving would follow if the resistance had doubled. Here only the push changed, and more push drives more flow.', 'The current would hold steady only if the resistance rose to match. The yarn is unchanged, so R is unchanged and I follows V.', null, 'Quadrupling is what the heat does, since P = V²/R. Current is proportional to the voltage, not its square.'] },
  { id: 'q-doubleR', ch: 'flow', q: 'Same battery, but the yarn’s resistance doubles. The current…', o: ['doubles', 'halves', 'stays the same', 'quarters'], a: 1, why: 'With the voltage fixed, I = V / R, so the current is inversely proportional to the resistance: twice the R lets half the current through.', hook: 'Twice the fight, half the flow.', no: ['That swaps resistance for conductance. More resistance lets less current through, not more.', null, 'That treats the current as set by the battery alone, whatever it is connected to. A battery fixes the voltage; the current it drives depends on the resistance it meets.', 'A quarter would need four times the resistance. Current goes as 1/R, not 1/R².'] },
  { id: 'q-sweat', ch: 'flow', q: 'A sweat droplet bridges two traces either side of a resistive sensor. The reading…', o: ['is unaffected: sweat barely conducts', 'reads low: some current bypasses the sensor', 'reads high: the sweat adds its resistance in series', 'stops: the sweat blocks the current'], a: 1, why: 'Salty water conducts. It becomes a parallel path, so less of the current goes through the sensor and the reading drifts.', no: ['Pure water barely conducts, but sweat carries salt, and a film of salty water conducts well enough to matter beside a sensor.', null, 'Series would mean the current had to pass through the droplet to reach the sensor. The droplet sits across the two traces, beside the sensor, so it is a second path.', 'A liquid lying across two traces can’t block anything; all it can do is add a route for current.'] },
  { id: 'q-loop', ch: 'flow', q: 'You sew one conductive thread from the battery’s + to an LED and stop. The LED…', o: ['lights dimly from the one thread', 'lights fully', 'doesn’t light: there’s no way back', 'lights only once you touch the thread'], a: 2, why: 'No loop, no flow. The current needs a path back to the − terminal.', no: ['One thread carries current only if the circuit comes back to the battery. With no return path there is no current at all, so no dim glow either.', 'The LED is pushed from one side but has nowhere to send the current, so none flows.', null, 'Touching the thread doesn’t connect it to the − terminal: your body isn’t part of the battery’s circuit, so there is still no way back.'] },
  // resist
  { id: 'q-length', ch: 'resist', q: 'Same yarn, twice as long. Its resistance…', o: ['halves', 'stays the same', 'doubles', 'quadruples'], a: 2, why: 'R = ρL/A. Long and thin, resistance wins: R scales with length.', no: ['Halving is what doubling the cross-section would do. A longer path gives the electrons more material to cross, so R goes up.', 'Resistivity stays the same because it belongs to the metal, but resistance counts the whole length of yarn.', null, 'Quadrupling needs the yarn to get longer and thinner together, as when a wire is drawn out. Here only the length doubles.'] },
  { id: 'q-ply', ch: 'resist', q: 'You ply two identical conductive yarns together. The resistance of the plied yarn is…', o: ['double', 'the same', 'half', 'a quarter'], a: 2, why: 'Two equal paths side by side are in parallel: R ÷ 2. More lanes, less jam.', no: ['Doubling would follow if the two yarns were joined end to end. Plied together they sit side by side and share the current.', 'Each yarn keeps its own resistance, but together they give the current twice the cross-section to flow through.', null, 'A quarter would need four equal yarns side by side. Two of them give half.'] },
  { id: 'q-rho', ch: 'resist', q: 'Which number describes the MATERIAL, whatever the yarn’s thickness?', o: ['Ω per metre (Ω/m)', 'Resistivity ρ (Ω·m)', 'Resistance end to end (Ω)', 'Resistance per gram (Ω/g)'], a: 1, why: 'ρ is the material property. Ω/m includes the cross-section — it’s the tex of conductivity.', no: ['Ω/m depends on how much metal is in the cross-section, so a thicker yarn of the same metal has a lower Ω/m.', null, 'End-to-end resistance depends on the length and the thickness as well, so it describes this one piece of yarn, not the metal.', 'A per-gram figure folds in the density and how the metal is spread through the yarn, so two yarns of one metal can differ.'] },
  { id: 'q-knit', ch: 'resist', q: 'Why does a conductive knit’s resistance change when it’s stretched?', o: ['The metal itself gets longer and thinner', 'Loops touch less: fewer paths across', 'Stretching warms the yarn and raises ρ', 'The yarn untwists and its filaments split'], a: 1, why: 'The fibre barely strains. What changes is how many loops touch and how hard: each touching point is a path for current between loops, so fewer contacts leave fewer paths and R rises.', hook: CONTACT.hook, no: ['The metal itself barely strains: the loops slide and open long before the fibre stretches measurably.', null, 'Stretching a knit makes almost no heat, and a change in ρ that small would be swamped by the change in how the loops touch.', 'Filaments can splay, but a split filament still conducts along its length. What changes the reading is where loops press on loops.'] },
  { id: 'q-colder', ch: 'resist', q: 'A heater line runs from a 5 V battery. You make the line twice as long. Total heat…', o: ['doubles', 'stays the same', 'halves', 'quadruples'], a: 2, why: 'P = V²/R. At fixed voltage, longer is colder.', no: ['Doubling holds at a fixed current (P = I²R), but a battery fixes the voltage, so the longer line draws less current.', 'Twice the length is twice the resistance, so at a fixed voltage the current halves and the heat changes with it.', null, 'Quadrupling would need the current to stay the same while the resistance quadrupled. Neither happens here.'] },
  { id: 'q-square', ch: 'resist', q: 'You double the current through the same heater yarn. Heat output…', o: ['doubles', 'quadruples', 'halves', 'stays the same'], a: 1, why: 'The heat made in a resistor is P = I²R. With R unchanged, twice the current gives 2² = 4 times the power.', hook: 'Heat goes with the square.', no: ['Doubling is right for the voltage across the yarn (V = IR), but the heat depends on the current squared.', null, 'Halving would follow from doubling the resistance on a fixed voltage. Here R stays the same and the current rises.', 'The yarn’s resistance hasn’t changed, but the heat depends on the current through it, and that doubled.'] },
  { id: 'q-parallel', ch: 'resist', q: 'A high-Ω/m yarn has to heat a big panel from 5 V. The usual answer is…', o: ['one long line zig-zagging across it', 'several shorter lines in parallel', 'a thinner yarn of the same kind', 'several lines joined end to end'], a: 1, why: 'Parallel lines cover the area while keeping total R low enough for useful power at low voltage.', no: ['One long line has a large resistance, and at 5 V a large resistance draws little current, so the panel barely warms.', null, 'A thinner yarn of the same kind has a higher Ω/m, which makes the low-power problem worse.', 'Lines joined end to end add their resistances, which is no different from one long line.'] },
  { id: 'q-hotspot', ch: 'resist', q: 'A series heater line has one thinned, damaged section. That section runs…', o: ['colder: less current gets through it', 'hotter', 'the same as the rest of the line', 'colder: it has less metal to heat'], a: 1, why: 'In series the current is the same everywhere. The damaged section has more R, so it makes more I²R heat — a hot spot.', no: ['In a single series line the same current passes every point, so the damaged section can’t get less of it.', null, 'With the same current everywhere, extra resistance in one section means extra I²R heat in that section.', 'Less metal gives that section a higher resistance, and in series a higher resistance heats more, not less.'] },
  // metals
  { id: 'q-rank', ch: 'metals', q: 'Rank by conductivity, best first:', o: ['Copper, silver, gold, aluminium', 'Silver, copper, gold, aluminium', 'Gold, silver, copper, aluminium', 'Silver, gold, copper, aluminium'], a: 1, why: 'Silver has the lowest resistivity of any metal, about 1.59 × 10⁻⁸ Ω·m, then copper (1.68), gold (2.44) and aluminium (2.65).', hook: 'Some Cats Get Angry: Ag, Cu, Au, Al.', no: ['Copper is the conductor you meet most often, but silver’s resistivity is about 5% lower.', null, 'Gold goes on contacts because it doesn’t tarnish, not because it conducts best; it comes third, behind silver and copper.', 'Gold’s resistivity is about 45% higher than copper’s, so copper ranks second, ahead of gold.'] },
  { id: 'q-plated', ch: 'metals', q: 'Why silver-PLATED nylon rather than solid silver yarn?', o: ['A plated skin conducts better than solid silver', 'Silver skin conducts; nylon is soft and cheap', 'Solid silver can’t be drawn into fine filaments', 'The nylon carries current too, alongside the silver'], a: 1, why: 'A micron-thin silver shell carries the current; the nylon core makes it sewable, flexible and affordable.', no: ['A thin skin holds less silver than a solid yarn, so it conducts worse; what it gains is flexibility and price.', null, 'Silver draws into very fine wire easily. A solid silver yarn would be costly and stiff to sew, not impossible to make.', 'Nylon is an insulator, so all of the current runs in the silver shell.'] },
  { id: 'q-gold', ch: 'metals', q: 'Why is gold used on connector contact faces?', o: ['It’s the best conductor of all', 'It doesn’t tarnish, so contacts stay clean', 'Thin gold plating is cheaper than silver plating', 'It solders more easily than silver'], a: 1, why: 'Gold goes where things touch. It isn’t the best conductor (silver and copper are); it’s the most stable surface.', no: ['Silver and copper both conduct better than gold.', null, 'Gold costs far more than silver weight for weight; it is used thinly because only the surface matters.', 'Gold dissolves into molten solder and can make the joint brittle, so soldering isn’t what it’s chosen for.'] },
  { id: 'q-copperdressed', ch: 'metals', q: 'Why is copper in a garment almost always enamelled, plated or alloyed?', o: ['Bare copper conducts poorly once it’s woven in', 'It corrodes in sweat and fatigues when flexed', 'Bare copper is too stiff to sew or knit at all', 'The coating is what lets the copper conduct'], a: 1, why: 'Copper is always dressed. The conductivity is excellent; the surface and fatigue life are the problems.', no: ['Copper conducts just as well woven in as out; only silver beats it.', null, 'Fine copper wire is soft enough to sew and knit, so stiffness isn’t what holds it back.', 'Enamel is an insulator. It protects the copper, and the copper does all the conducting.'] },
  { id: 'q-nickel', ch: 'metals', q: 'Which is the most common skin contact allergen?', o: ['Silver', 'Gold', 'Nickel', 'Copper'], a: 2, why: 'Nickel near skin = itch. Watch for it in snap plating and as the barrier under gold.', no: ['Silver allergy is rare; silver is even used in wound dressings against the skin.', 'Gold is one of the least reactive metals and rarely causes a reaction, though the nickel often plated under it can.', null, 'Copper can stain skin green and irritate a few people, but nickel allergy is far more common.'] },
  { id: 'q-steel', ch: 'metals', q: 'Stainless steel’s resistivity compared to copper’s is roughly…', o: ['about the same', 'about 4× higher', 'about 40× higher', 'about 400× higher'], a: 2, why: 'About 7.2 × 10⁻⁷ against 1.68 × 10⁻⁸ Ω·m: 43 times. Washes forever, conducts like a tax.', no: ['Stainless is an alloy of iron, chromium and nickel, and the mix of atoms scatters electrons, so it conducts far worse than pure copper.', 'Four times would put stainless close to nickel. Its resistivity is about ten times higher than that.', null, 'Four hundred times would make stainless worse than nichrome heater wire, which is about 65 times copper.'] },
  { id: 'q-nichrome', ch: 'metals', q: 'Why do heaters use nichrome or stainless rather than copper?', o: ['They conduct better than copper, so they heat faster', 'Their higher ρ gives a useful R in a short length', 'They hold heat longer once they’re warm', 'Copper would melt at heating temperatures'], a: 1, why: 'Copper’s R is so low you’d need metres to make a few ohms. Nichrome also holds its R steady as it heats.', no: ['They conduct worse than copper, and that is the point: a heater needs resistance to turn current into heat.', null, 'How long a wire stays warm depends on its mass and its insulation, not on which alloy it is.', 'Garment heaters run at about 40–50 °C, far below copper’s 1,085 °C melting point. Copper’s problem is its low resistance.'] },
  { id: 'q-tcr', ch: 'metals', q: 'A yarn that measures temperature along a sleeve should have…', o: ['a resistance that stays put as the sleeve warms', 'a large, predictable change of R with heat', 'the lowest resistivity it can have', 'a high resistance, so it heats itself'], a: 1, why: 'Heaters want steady; thermometers want swingy. Platinum, copper and nickel change about 0.4–0.6% per °C.', no: ['A resistance that stays put is what a heater or a strain gauge wants. A thermometer needs R to change, or there is nothing to read.', null, 'Low resistivity says nothing about how R changes with heat: copper is low and changes, constantan is higher and barely does.', 'A sensor that heats itself reads its own warmth, not the sleeve’s, so a thermometer yarn should carry as little current as it can.'] },
  { id: 'q-migration', ch: 'metals', q: 'Two silver traces sit close together under DC voltage in a humid garment. Over time they can…', o: ['become better insulated as the moisture dries out', 'grow silver needles across the gap and short', 'dissolve away completely into the moisture', 'stay as they are: silver is too noble to move'], a: 1, why: 'Electrochemical migration: silver walks in the wet. Spacing and encapsulation prevent it.', no: ['Drying stops the process, but the damage is done while the moisture is there: silver ions move across under the voltage and redeposit.', null, 'Only a little silver dissolves, and it redeposits on the other trace as needles rather than washing away.', 'Silver resists ordinary corrosion, but under DC in water it dissolves at the positive trace and travels; it is the metal most prone to this.'] },
  { id: 'q-galvanic', ch: 'metals', q: 'A copper trace touches a silver snap and both sit in sweat. What corrodes?', o: ['The silver', 'The copper', 'Neither: both are metals', 'Both equally'], a: 1, why: 'Two metals plus an electrolyte make a battery. Copper is less noble than silver, so copper gives up electrons and dissolves.', no: ['Silver is the more noble metal of the pair, so it is the side that gets protected.', null, 'Two different metals in an electrolyte form a cell; being metals is exactly what lets them do it.', 'The pair splits the roles: one metal gives up electrons and dissolves while the other is protected.'] },
  { id: 'q-solder', ch: 'metals', q: 'Why don’t you just solder silver-plated nylon thread to a board?', o: ['Silver doesn’t take solder at all', 'Nylon melts near soldering temperatures', 'Solder would short the filaments together', 'Solder conducts too poorly for a sensor'], a: 1, why: 'Nylon melts around 220–260 °C, and a soldering iron runs hotter than that. Crimp, sew, or use conductive adhesive.', no: ['Silver takes solder well; it is even an ingredient in common solders.', null, 'Joining the filaments to each other does no harm, since they all carry the same signal anyway.', 'Solder is a metal alloy and conducts far better than any sensor material.'] },
  { id: 'q-pedot', ch: 'metals', q: 'PEDOT:PSS’s main weakness in a garment is…', o: ['stiffness: it cracks when flexed', 'water: humidity and washing', 'weight: it adds a lot of mass', 'cost: it’s pricier than silver'], a: 1, why: 'Paint that conducts, and water is its enemy: the PSS half absorbs moisture and swells.', no: ['PEDOT:PSS films are thin and bend well; cracking is a bigger risk for printed silver.', null, 'It goes on as a coating a few microns thick, so it adds almost no mass.', 'It is used in thin coats, so its cost per garment is modest; price isn’t what limits it.'] },
  // sense
  { id: 'q-core', ch: 'sense', q: 'The core difference between resistive and capacitive sensing:', o: ['Resistive uses metal; capacitive uses carbon', 'R: current crosses it. C: a gap stores charge', 'Capacitive needs pressure; resistive doesn’t', 'Resistive senses touch; capacitive senses heat'], a: 1, why: 'A resistive sensor is a conducting path: current flows through it, and pressure or stretch changes how easily. A capacitive sensor is two conductors with a gap: no current crosses, and it measures how much charge the gap can hold.', hook: 'R is a Road, C is a Canyon.', no: ['Either kind can be made with metal or carbon; the difference is how the electricity behaves, not the material.', null, 'If anything it runs the other way: resistive pressure sensors need force, while a capacitive pad can register a light touch.', 'Both can sense touch, and neither is mainly a heat sensor.'] },
  { id: 'q-halfgap', ch: 'sense', q: 'You press a capacitive pad and the gap halves. Capacitance…', o: ['halves', 'doubles', 'stays the same', 'quadruples'], a: 1, why: 'Capacitance is C = ε₀εᵣA/d, inversely proportional to the gap d: halve the gap and the plates hold twice the charge at the same voltage.', hook: 'Smaller gap, more C.', no: ['That treats C as proportional to the gap. It is the reverse: plates closer together hold more charge.', null, 'That treats capacitance as a property of the plates alone. How much charge two plates hold at a given voltage depends on how far apart they are.', 'Quadrupling would need C to go as 1/d², but it goes as 1/d.'] },
  { id: 'q-area', ch: 'sense', q: 'Double the overlap area of the two electrodes. Capacitance…', o: ['halves', 'doubles', 'quadruples', 'stays the same'], a: 1, why: 'C = ε₀εᵣA/d is proportional to the overlap area A: twice the facing area holds twice the charge at the same voltage.', hook: 'Bigger plates, more C.', no: ['Halving would follow if C went as 1/A, the way resistance goes with cross-section. More plate area holds more charge, not less.', null, 'Quadrupling would need C to go as A², but each patch of overlap adds its own share, so it is linear.', 'Only the overlapping area counts, and the overlap doubled.'] },
  { id: 'q-eps', ch: 'sense', q: 'Replace an air gap (εᵣ ≈ 1) with a polyester film (εᵣ ≈ 3) of the same thickness. Capacitance…', o: ['stays the same', 'triples', 'drops to a third', 'rises by about 1.7×'], a: 1, why: 'C = ε₀εᵣA/d is proportional to εᵣ. The polyester’s molecules polarise in the field, which lets the plates hold three times the charge at the same voltage.', hook: 'Better filling: C scales with εᵣ.', no: ['The gap and area are unchanged, but εᵣ is in the formula too, and it went from 1 to 3.', null, 'That would follow if C went as 1/εᵣ. A material that polarises lets the plates hold more charge, not less.', '1.7 is about √3, but C scales with εᵣ itself, not its square root.'] },
  { id: 'q-touchless', ch: 'sense', q: 'Which can sense a hand hovering a couple of centimetres away?', o: ['Resistive', 'Capacitive', 'Both', 'Neither'], a: 1, why: 'A body is a conductor; its field changes the electrode’s capacitance without touching. Resistive needs contact and force.', no: ['A resistive sensor changes only when pressure changes its contacts, and a hovering hand presses on nothing.', null, 'Only one of the two works without contact, because resistive needs force on the sensor.', 'A body nearby changes the electric field around an electrode, and a capacitive sensor reads exactly that.'] },
  { id: 'q-measure', ch: 'sense', q: 'A capacitive sensor is typically read by…', o: ['a voltage divider, like a resistive one', 'timing how long it takes to charge', 'measuring the current through the gap', 'measuring the DC resistance between plates'], a: 1, why: 'C is a bucket: bigger bucket, longer to fill.', no: ['A divider reads a steady resistance, and a capacitor blocks steady current, so the divider would see an open circuit.', null, 'No current crosses the gap; charge only flows on and off the plates while they charge.', 'The DC resistance between the plates is effectively infinite whatever you do, so it carries no reading.'] },
  { id: 'q-mutual', ch: 'sense', q: 'In a mutual-capacitance touch sensor, a finger approaching makes the measured capacitance…', o: ['go up', 'go down', 'stay the same', 'go up, then down'], a: 1, why: 'Self: you add. Mutual: you steal. The finger diverts field lines away from the receive electrode.', no: ['Up is what a self-capacitance pad reads. A mutual sensor measures the coupling between two electrodes, and a finger takes some of that away.', null, 'A finger is a conductor loosely tied to ground, so it changes the field between the electrodes as it comes near.', 'The change runs one way as the finger approaches: the closer it gets, the more coupling it removes.'] },
  { id: 'q-self', ch: 'sense', q: 'In a self-capacitance sensor, a finger approaching makes the measured capacitance…', o: ['go up', 'go down', 'stay the same', 'go down, then up'], a: 0, why: 'Self: you add. The body becomes extra plate area to ground.', no: [null, 'Down is the mutual-capacitance reading. A self-capacitance pad measures its own capacitance to ground, and a body nearby adds to it.', 'A finger is a large conductor coupled to ground, so as it nears the pad the pad’s capacitance changes.', 'The reading rises steadily as the finger approaches; nothing makes it dip first.'] },
  { id: 'q-water', ch: 'sense', q: 'Why does a sweaty or rain-soaked shirt confuse a capacitive sensor?', o: ['Water insulates the plates from the finger', 'Water’s εᵣ ≈ 80 reads as a big touch', 'Water cools the sensor and shifts its zero', 'Wet fabric shrinks and moves the plates apart'], a: 1, why: 'Water’s relative permittivity is about 80, against about 3 for most fabrics, and salty sweat also conducts. A wet patch adds capacitance like a large finger, so the sensor reads a touch that isn’t there.', hook: 'Water fools C and shorts R.', no: ['Water, and especially salty sweat, polarises and conducts, so it couples the plates more strongly rather than insulating them.', null, 'Temperature does shift a reading slightly, but the large effect is the water itself sitting in the electric field.', 'Wet fabric changes size far too little and too slowly to explain a sudden false touch.'] },
  { id: 'q-shield', ch: 'sense', q: 'Why does a capacitive pressure pad on the thigh need a grounded shield layer?', o: ['To keep sweat and rain away from the sense plate', 'The body’s ~100 pF swamps the ~1 pF signal', 'To spread the pressure evenly across the pad', 'To carry the return current'], a: 1, why: 'A leg near the sense plate adds about 100 pF to ground, while a press changes the plate by about 1 pF, so the body would swamp the signal. A grounded layer between the plate and the leg takes the body’s field instead.', hook: 'Shield the sense plate so it only sees the press, not the leg.', no: ['A shield is a conductor, not a moisture barrier; keeping sweat out is the encapsulation’s job.', null, 'Spreading the load is the job of a spacer or stiffener; a thin grounded layer doesn’t change the pressure.', 'A capacitive pad has no steady return current. The shield’s job is electric, between the sense plate and the body.'] },
  { id: 'q-creep', ch: 'sense', q: 'A known weakness of carbon-polymer resistive pressure sensors:', o: ['They can’t measure a steady force at all, only changes', 'Creep under a steady load, and hysteresis', 'They need a high supply voltage to read', 'Their range is too narrow for a hand'], a: 1, why: 'Carbon-polymer composites are viscoelastic. Under a steady load the polymer keeps flowing, so the reading drifts (creep), and on release it comes back by a different path (hysteresis).', hook: 'Polymers remember.', no: ['They do read a steady force; the trouble is that the reading wanders while the force stays the same.', null, 'They run happily from 3.3 V in a divider, so supply voltage isn’t the issue.', 'Their range easily covers a hand’s grip; the weakness is how the reading behaves over time.'] },
  { id: 'q-switch', ch: 'sense', q: 'Two conductive fabrics with only an open mesh spacer between them (no carbon layer). Press it and you get…', o: ['a pressure sensor with a smooth range', 'an on/off switch', 'a capacitor that reads the press', 'a strain sensor'], a: 1, why: 'With only holes between them, the fabrics either touch through the mesh or they don’t. Pressure can’t make the contact partly conductive, so the circuit is simply open or closed.', hook: 'No middle layer, no middle values.', no: ['A smooth range needs a layer whose resistance falls gradually with pressure, like a carbon-loaded polymer. Bare fabric on fabric jumps from open to closed.', null, 'The fabrics form a capacitor only while they are apart; once pressed through the mesh they touch and short it out.', 'A strain sensor responds to stretch along the fabric; this stack responds to being pressed together.'] },
  { id: 'q-divider', ch: 'sense', q: 'Sensor and fixed resistor in series across 3.3 V; you read the voltage across the fixed resistor. Press the sensor (its R drops). The reading…', o: ['rises', 'falls', 'stays the same', 'rises, then falls'], a: 0, why: 'The sensor’s share of the push shrinks, so the fixed resistor’s share grows.', no: [null, 'Falls is what you would read across the sensor itself. The fixed resistor’s voltage goes up as the sensor’s goes down.', 'That treats the fixed resistor’s voltage as depending on that resistor alone. Its share of the 3.3 V depends on the sensor beside it, which just dropped.', 'The sensor’s R drops steadily as you press, so the reading moves one way only.'] },
  { id: 'q-constantan', ch: 'sense', q: 'Strain gauges use constantan because…', o: ['it conducts best of the common alloys', 'its R barely changes with temperature', 'it stretches further before it yields', 'it’s the cheapest wire to make thin'], a: 1, why: 'Heaters want steady; thermometers want swingy — and a strain gauge wants steady too, so heat doesn’t fake a strain.', no: ['Constantan conducts about 30 times worse than copper; a strain gauge doesn’t need low resistance.', null, 'A gauge is strained only a fraction of a percent, well inside any metal’s elastic range, so stretch isn’t the constraint.', 'Copper and steel wire are both cheaper; price isn’t what decides a gauge alloy.'] },
  // stack
  { id: 'q-tpubase', ch: 'stack', q: 'Why does printed silver ink go on a TPU base layer instead of straight onto fabric?', o: ['The TPU conducts too and lowers the trace’s R', 'Ink needs a continuous floor; fabric wicks it', 'It keeps the silver from tarnishing underneath', 'It makes the ink cure faster in the oven'], a: 1, why: 'Fabric is full of gaps between the yarns. Ink printed straight onto it wicks into the fibres and breaks into islands, leaving the trace uneven or open; a TPU layer gives it a continuous, sealed surface to sit on.', hook: 'Fabric is a sieve; TPU is a floor.', no: ['TPU is an insulator; the trace’s resistance comes from the silver alone.', null, 'Tarnish attacks the exposed top of a trace, so a layer underneath doesn’t prevent it; a cover layer does.', 'Curing time is set by the ink and the oven temperature, not by what lies underneath.'] },
  { id: 'q-compress', ch: 'stack', q: 'Why do dry EMG garments use compression over the electrodes?', o: ['To squeeze the muscle so it signals louder', 'Steady contact means steady impedance', 'To press sweat out from under the electrode', 'To stop the electrode sliding off the snap'], a: 1, why: 'The skin–electrode contact has an impedance that depends on how firmly they meet. If the electrode shifts, that impedance changes and the change shows up in the signal as motion artefact; compression holds the contact steady.', hook: 'Contact pressure is signal quality.', no: ['Squeezing doesn’t make the muscle’s electrical signal stronger; it changes how cleanly the electrode picks it up.', null, 'Dry electrodes work better once a little sweat builds up under them, so pushing it out isn’t the aim.', 'The snap holds the electrode to the garment mechanically; compression works on the electrode against the skin.'] },
  { id: 'q-baretrace', ch: 'stack', q: 'The trace from an EMG electrode to its snap is left bare against the skin. Result?', o: ['Nothing changes: only the electrode counts', 'It picks up signal along its whole length', 'It heats up from the current it carries', 'It shorts the snap to the skin'], a: 1, why: 'Any exposed conductor touching skin picks up the skin’s voltage. A bare trace collects signal along its whole length, from muscles the electrode isn’t over, and blurs the reading.', hook: 'A bare trace is a second electrode.', no: ['The amplifier can’t tell which conductor touched the skin; anything conducting against the body adds to the signal.', null, 'EMG currents are microamps, far too small to heat a trace measurably.', 'Skin is a poor conductor and everything here is at signal level, so the trouble is extra pickup, not a short.'] },
  { id: 'q-heaterins', ch: 'stack', q: 'Why does a heated jacket panel have insulation on the outer side of the heater?', o: ['To stop the heater shorting to the shell fabric', 'So the heat goes to the body, not the air', 'To make the panel stiff enough to hold', 'To keep rain off the heater yarn'], a: 1, why: 'A heater warms whatever is on both sides of it. Insulation on the outer side slows the heat leaving into the air, so most of it goes inward to the body.', hook: 'Heat flows both ways.', no: ['The heater yarn is already insulated or encapsulated; the outer layer is there for heat, not electrical safety.', null, 'A heated panel should stay soft, so stiffness would be a cost, not the goal.', 'The shell fabric keeps rain out; the insulation’s job is where the heat goes.'] },
  // 06
  { id: 'q-strain', ch: 'stretch', q: 'A 200 mm strap is stretched to 230 mm. What is the strain?', o: ['30 mm', '0.15 (15%)', '0.87', '1.15 (115%)'], a: 1, why: 'Strain is stretch per length: 30 / 200 = 0.15.', no: ['30 mm is the extension. Strain divides it by the original length, so it has no units.', null, '0.87 is 200 ÷ 230, the old length over the new. Strain is the change over the original.', '1.15 is the new length over the old. Strain counts only the change, 0.15.'] },
  { id: 'q-young', ch: 'stretch', q: 'Which property says how much stress a material needs per unit of stretch, in its straight first region?', o: ['Poisson’s ratio', 'Young’s modulus', 'Yield strain', 'Gauge factor'], a: 1, why: 'Young’s modulus is the slope of the stress–strain curve in its straight first region: the stress needed for each unit of strain. A high E is a stiff material.', hook: 'Stiffness is stress over strain: E = σ / ε.', no: ['Poisson’s ratio describes how much a material narrows as it stretches, not how hard it is to stretch.', null, 'Yield strain is where the straight region ends, not its slope.', 'Gauge factor is how much resistance changes per unit of strain; it says nothing about the force needed.'] },
  { id: 'q-stiffest', ch: 'stretch', q: 'Which is the stiffest (highest Young’s modulus)?', o: ['Silicone', 'TPU', 'Polyester fibre', 'Copper'], a: 3, why: 'Copper ~120 GPa, polyester fibre ~10, TPU ~0.01–0.05, silicone ~0.001 (soft grades less).', no: ['Silicone is the softest here, around 1 MPa or less.', 'TPU is a soft elastomer, a few tens of MPa.', 'Polyester fibre is stiff for a polymer, about 10 GPa, but copper is around twelve times stiffer still.', null] },
  { id: 'q-yield', ch: 'stretch', q: 'Roughly how far can copper stretch and still spring back?', o: ['About 0.1%', 'About 2%', 'About 10%', 'About 30%'], a: 0, why: 'Metal only springs back a tiny bit: about 0.03–0.3%, low for soft (annealed) copper, high for hard-drawn.', no: [null, '2% is far past copper’s elastic limit; the wire would stay bent.', '10% is a figure for elastomers or knits. A metal yields long before that.', '30% is closer to how far soft copper stretches before it breaks, and almost all of that is permanent.'] },
  { id: 'q-poisson', ch: 'stretch', q: 'A strip with ν = 0.4 is stretched 5%. About how much narrower does it get?', o: ['0.4%', '2%', '5%', '9%'], a: 1, why: 'Poisson’s ratio is narrowing per unit of stretch: width change ≈ −ν × stretch. So the strip gets 0.4 × 5% = 2% narrower.', no: ['0.4% treats ν as the narrowing itself. ν is a ratio, so multiply it by the stretch.', null, '5% would mean ν = 1, narrowing as much as it stretches; at ν = 0.4 it narrows less.', '9% adds the two numbers. The narrowing is their product.'] },
  { id: 'q-rubber', ch: 'stretch', q: 'Rubber’s Poisson’s ratio is close to 0.5. What does that mean?', o: ['It doesn’t narrow at all', 'It keeps its volume as it stretches', 'It gets wider as it stretches', 'It loses half its volume at double length'], a: 1, why: 'For small stretches the volume changes by (1 − 2ν) times the stretch. At ν = ½ that is zero: rubber narrows just enough to keep its volume.', no: ['ν = 0 is the no-narrowing case. At 0.5 it narrows by half the stretch in each sideways direction.', null, 'Getting wider needs a negative ν, as in auxetic structures.', 'Losing volume would need ν well below 0.5; at 0.5 the volume is exactly kept.'] },
  { id: 'q-auxetic', ch: 'stretch', q: 'You pull a re-entrant (bow-tie cell) spacer and it gets wider. What is its Poisson’s ratio?', o: ['Negative', 'Zero', 'About 0.3', 'About 0.5'], a: 0, why: 'ν is minus the sideways strain over the lengthwise strain. If a pull makes the spacer wider, the sideways strain is positive too, so ν comes out negative.', hook: 'Auxetics get fatter when you pull: ν < 0.', no: [null, 'Zero would mean it keeps its width as it stretches; this one got wider.', '0.3 is typical of metals, which narrow when pulled.', '0.5 is rubber, which narrows to keep its volume.'] },
  { id: 'q-gauge', ch: 'stretch', q: 'A liquid-metal channel in silicone is stretched 10%. Roughly how much does its resistance rise?', o: ['About 5%', 'About 10%', 'About 21%', 'About 33%'], a: 2, why: 'Longer and thinner: R × (1.1)² = 1.21. Gauge factor about 2.', no: ['5% would need the channel to get shorter or wider. Stretching makes it longer and thinner, which raises R by more than the stretch.', '10% counts the extra length but forgets that the channel also gets thinner as it stretches.', null, '33% would need a gauge factor above 3; a liquid in a sealed channel gives about 2.'] },
  { id: 'q-cap', ch: 'stretch', q: 'A silicone capacitor with soft electrodes is stretched to 1.5 × its length. Its capacitance goes…', o: ['down to about 0.67×', 'unchanged', 'up to about 1.5×', 'up to about 2.25×'], a: 2, why: 'Silicone keeps its volume. Stretched to 1.5 × its length, the electrodes’ area grows by √1.5 while the layer between them thins by the same factor, and C ∝ A/d, so C rises 1.5 times.', no: ['0.67 is what you would get if stretching only pulled the plates apart. In fact the layer thins, so the plates get closer.', 'C would stay put only if the gap grew as the area did, but a layer that keeps its volume thins as it stretches.', null, '2.25 is 1.5². The strip narrows as it lengthens, so the area grows by only √1.5.'] },
  { id: 'q-island', ch: 'stretch', q: 'A rigid battery pod is bonded to a stretchy sleeve. Where does the sleeve stretch most?', o: ['Under the middle of the pod', 'Right at the pod’s edges', 'Evenly, all along the sleeve', 'At the cuff, furthest from it'], a: 1, why: 'The pod can’t stretch, so neither can the sleeve under it. The stretch the sleeve has to take is pushed around the pod and concentrates at the boundary between stiff and soft.', hook: 'Stiff on soft breaks at the edge.', no: ['Under the middle, the bonded pod holds the sleeve still; it barely stretches there.', null, 'Even stretch needs the same stiffness all along the sleeve, and the pod breaks that.', 'The cuff stretches with the arm, but the largest local strain is where stiff meets soft.'] },
  { id: 'q-serp', ch: 'stretch', q: 'Why is a printed trace drawn as a wave across a stretch panel?', o: ['To match the look of the knit under it', 'The wave flattens, so the metal bends', 'A longer path spreads the current, lowering R', 'Loops cancel interference picked up nearby'], a: 1, why: 'Straightening a wave needs only a little bending in each curve, so the metal’s own strain stays far below its elastic limit even when the panel stretches a lot.', hook: 'Serpentines turn stretch into bend.', no: ['Looks aren’t the reason: a straight trace would crack at a few tenths of a percent of stretch.', null, 'A longer path raises resistance, the opposite of lowering it.', 'Cancelling interference takes paired or twisted conductors; a single wavy trace cancels nothing.'] },
  { id: 'q-cube', ch: 'stretch', q: 'You halve the thickness of a TPU laminate film. Its bending stiffness becomes…', o: ['½', '¼', '⅛', 'the same'], a: 2, why: 'Bending stiffness goes with thickness cubed: (½)³ = ⅛.', no: ['Half is right for stretching stiffness, which goes with thickness. Bending goes with its cube.', 'A quarter counts two of the three factors: the strain at the surface, the lever arm and the amount of material each scale with thickness.', null, 'That treats bending stiffness as a property of the material alone. The material sets E, but how hard a sheet is to bend also depends on how thick it is.'] },
];

